/* Delivery governance shared with the customer: action items, decisions, RAID log, sign-offs (BRD / UAT / go-live)
   with evidence and history, meeting minutes, module owners, weekly digest, and change requests with a Facilio-only
   value and slippage dashboard. Records live in project_items; the server enforces what customers may change. */
(function (root) {
  'use strict';
  const F = root.FWB; const { S, esc } = F; const V = root.FWBViews; const ACT = V.ACT; const I = () => V.items;
  const { tag, drawer, closeDrawer, toast, ico, confirmDialog } = V;
  const cust = () => V.isCustomer();
  const canEdit = () => !S.readonly || cust();
  const fac = () => !cust() && !S.readonly;
  const own = () => fac() && S.project && S.project.role === 'owner';   // recording or undoing a sign-off is for owners and admins (enforced on the server too)
  const val = id => { const el = document.getElementById(id); return el ? (el.type === 'checkbox' ? el.checked : el.value.trim()) : ''; };
  const fmt = d => (d ? V.fmtDate(d) : '—');
  const custName = () => (S.project && S.project.customer) || 'Customer';
  const cur = () => (F.doc('contract') && F.doc('contract').currency) || (S.ws.project.currency) || 'AED';
  const money = n => (n || n === 0 ? cur() + ' ' + Number(n).toLocaleString(undefined, { maximumFractionDigits: 2 }) : '—');

  // ================= action items =================
  const ACT_ST = ['Open', 'In progress', 'Blocked', 'Done'];
  // Open · Delayed N d · Closed · Closed late N d (Blocked counts as open, shown red)
  function itemState(a) {
    const t = V.today();
    if (a.status === 'Done') { const closed = (a.doneAt || a._at || '').slice(0, 10); const late = a.due && closed && closed > a.due ? V.daysBetween(a.due, closed) : 0; return late ? { k: 'late', label: 'Closed · ' + late + 'd late', cls: 'tbc' } : { k: 'closed', label: 'Closed', cls: 'green' }; }
    if (a.due && a.due < t) return { k: 'delayed', label: 'Delayed · ' + V.daysBetween(a.due, t) + 'd', cls: 'red' };
    return { k: 'open', label: a.status === 'Blocked' ? 'Blocked' : a.status === 'In progress' ? 'In progress' : 'Open', cls: a.status === 'Blocked' ? 'red' : 'blue' };
  }
  V.itemState = itemState;
  V.actionsFor = place => I().list('action').filter(a => !place || (a.mod || 'project') === place);
  V.actionsBlock = function (place, opts) {
    opts = opts || {}; I().load(['action']);
    if (!I().ready(['action'])) return '<div class="small muted">Loading actions…</div>';
    const list = V.actionsFor(place).sort((a, b) => (a.status === 'Done') - (b.status === 'Done') || (a.due || '9').localeCompare(b.due || '9'));
    const side = sd => list.filter(a => (a.side || 'facilio') === sd);
    const allowed = canEdit() && V.custAllow('actions');
    const table = (sd, title) => { const rows = side(sd); return `<div class="card" style="margin-bottom:12px"><div class="card-h"><h3>${esc(title)}</h3><span class="small muted">${rows.filter(a => a.status !== 'Done').length} open</span>${allowed && (fac() || sd === 'customer') ? `<button class="btn sm" data-act="actAdd" data-place="${esc(place || 'project')}" data-side="${sd}">${ico('plus')}Action</button>` : ''}</div>
      <div class="tbl-wrap" style="border:0;border-radius:0"><table class="tbl"><thead><tr><th>Action</th>${place ? '' : '<th>Area</th>'}<th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(a => { const s = itemState(a); const mine = fac() || (a.side === 'customer');
        return `<tr><td class="small">${esc(a.text)}${a.from ? `<div class="xs muted">From ${esc(a.from)}</div>` : ''}</td>${place ? '' : `<td class="small">${esc(V.modLabel(a.mod))}</td>`}<td class="small">${esc(a.owner || '—')}</td><td class="small">${fmt(a.due)}</td>
          <td>${allowed ? `<select data-change="actStatus" data-id="${esc(a.id)}" style="height:28px;width:120px">${ACT_ST.map(x => `<option ${x === a.status ? 'selected' : ''}>${x}</option>`).join('')}</select> ` : ''}${tag(s.cls, s.label)}</td>
          <td class="acts">${allowed && mine ? `<button class="btn sm ghost" data-act="actEdit" data-id="${esc(a.id)}" aria-label="Edit">${ico('edit')}</button>` : ''}${fac() ? `<button class="btn sm ghost" data-act="actDel" data-id="${esc(a.id)}" aria-label="Delete">${ico('trash')}</button>` : ''}</td></tr>`; }).join('') || `<tr><td colspan="6" class="empty small">No actions.</td></tr>`}</tbody></table></div></div>`; };
    return (opts.title ? `<div class="pink-label">${esc(opts.title)}</div>` : '') + table('customer', 'Due from ' + custName()) + table('facilio', 'Due from Facilio');
  };
  function actionForm(a, place, sd) {
    const own = fac() || !a || a.side === 'customer';
    return `<div class="fgrid"><div class="full"><label class="f">Action</label><textarea id="ac_text" rows="3" ${own ? '' : 'disabled'}>${esc(a ? a.text : '')}</textarea></div>
      ${fac() ? `<div><label class="f">Whose action</label><select id="ac_side"><option value="customer" ${(a ? a.side : sd) === 'customer' ? 'selected' : ''}>${esc(custName())}</option><option value="facilio" ${(a ? a.side : sd) === 'facilio' ? 'selected' : ''}>Facilio</option></select></div>` : ''}
      <div><label class="f">Area</label><select id="ac_mod" ${own ? '' : 'disabled'}>${V.moduleOptions(a ? a.mod : place, [{ v: 'project', l: 'Project' }, { v: 'kickoff', l: 'Kick-off' }, { v: 'uat', l: 'UAT' }, { v: 'golive', l: 'Go-live' }])}</select></div>
      <div><label class="f">Owner</label><input type="text" id="ac_owner" value="${esc(a ? a.owner || '' : '')}"></div><div><label class="f">Due date</label><input type="date" id="ac_due" value="${esc(a ? a.due || '' : '')}" ${own ? '' : 'disabled'}></div></div>`;
  }
  ACT.actAdd = a => drawer('New action', actionForm(null, a.getAttribute('data-place'), a.getAttribute('data-side')), `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="actSave">Add</button>`);
  ACT.actEdit = a => { const x = I().get('action', a.getAttribute('data-id')); drawer('Edit action', actionForm(x), `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="actSave" data-id="${esc(x.id)}">Save</button>`); };
  ACT.actSave = a => V.busy(a, async () => { const id = a.getAttribute('data-id'); const old = id ? I().get('action', id) : null; const text = val('ac_text'); if (!text) { V.ui.field('ac_text', 'Describe the action'); return; }
    const d = Object.assign({}, old || { status: 'Open' }, { text, mod: val('ac_mod') || 'project', owner: val('ac_owner'), due: val('ac_due') }); if (fac()) d.side = val('ac_side'); else if (!old) d.side = 'customer';
    await I().put('action', id || I().uid('a'), d); closeDrawer(); toast(id ? 'Action updated' : 'Action added'); });
  ACT.actStatus = el => V.busy(null, async () => { const x = I().get('action', el.getAttribute('data-id')); const d = Object.assign({}, x, { status: el.value }); if (el.value === 'Done') d.doneAt = x.doneAt || new Date().toISOString(); else delete d.doneAt; await I().put('action', x.id, d); });
  ACT.actDel = async a => { if (!(await confirmDialog('Delete action', 'Delete this action?', 'Delete', true))) return; await I().del('action', a.getAttribute('data-id')); };
  // lines like "C: Priya — share the site list by 2026-11-10" or "F: send templates" become actions
  V.actionsFromLines = async (text, mod, from) => { let n = 0; for (const raw of String(text || '').split('\n')) { const l = raw.trim(); if (!l) continue; const m = /^(c|customer|f|facilio)\s*[:\-]\s*(.*)$/i.exec(l); const side = m && /^c/i.test(m[1]) ? 'customer' : 'facilio'; let body = m ? m[2] : l; const due = (body.match(/\b(\d{4}-\d{2}-\d{2})\b/) || [])[1] || ''; body = body.replace(/\s*(by|due)?\s*\d{4}-\d{2}-\d{2}\s*/i, ' ').trim(); const om = /^([^—–-]{2,40})\s+[—–-]\s+(.*)$/.exec(body); await I().put('action', I().uid('a'), { text: om ? om[2] : body, owner: om ? om[1].trim() : '', side, due, mod: mod || 'project', status: 'Open', from: from || '' }, { silent: true }); n++; } V.render(); return n; };

  // ================= governance page =================
  const SIGNOFFS = [['brd', 'BRD Sign-Off', 'Step 3 · confirms the business requirements before build'], ['uat', 'UAT Sign-Off', 'Step 9 · confirms the system passed user acceptance testing'], ['golive', 'Go-Live Acceptance', 'Step 12 · confirms go-live and the start of hypercare']];
  const SO_ST = { notdue: ['low', 'Not due'], requested: ['tbc', 'Pending'], signed: ['green', 'Signed'], concern: ['red', 'Concern raised'] };
  const RAID_T = { R: 'Risk', A: 'Assumption', I: 'Issue', D: 'Dependency' }; const IMPACT = ['High', 'Medium', 'Low']; const RAID_ST = ['Open', 'Mitigating', 'Closed'];
  const DEC_ST = ['Proposed', 'Agreed', 'Superseded'];
  const KINDS = ['action', 'signoff', 'raid', 'decision', 'minutes', 'owner', 'digest', 'cr'];
  const rt = r => { const t = String(r.type || 'R'); return RAID_T[t] ? t : (Object.keys(RAID_T).find(k => RAID_T[k].toLowerCase() === t.toLowerCase()) || 'R'); };   // the badge is one letter even when an item holds the word
  V.governance = { html() {
    I().load(KINDS); const tab = S.ui.govTab || 'pmo';
    const tabs = [['pmo', 'PMO overview'], ['signoffs', 'Sign-offs'], ['raid', 'RAID log'], ['decisions', 'Decisions'], ['actions', 'Actions'], ['minutes', 'Meeting minutes'], ['owners', 'Module owners']].concat(fac() ? [['digest', 'Weekly digest']] : []);
    const head = `<div class="page-header"><div class="t"><h1>${cust() ? 'Governance' : 'Governance & RAID'}</h1><p>Sign-offs, risks, decisions, actions and minutes shared between ${esc(custName())} and Facilio. Every change is recorded with who made it and when.</p></div></div>
      <div class="tabs">${tabs.map(([k, l]) => `<button class="tab${tab === k ? ' active' : ''}" data-act="govTab" data-v="${k}">${esc(l)}</button>`).join('')}</div>`;
    if (!I().ready(KINDS)) return head + '<div class="page-body"><div class="empty">Loading…</div></div>';
    const so = I().list('signoff'); const raid = I().list('raid'); const open = raid.filter(r => r.status !== 'Closed');
    const facts = `<div class="grid g4" style="margin-bottom:16px"><div class="card stat"><div class="v">${so.filter(x => x.status === 'signed').length} / 3</div><div class="l">Sign-offs</div></div><div class="card stat"><div class="v">${open.length}</div><div class="l">Open RAID items</div></div><div class="card stat"><div class="v" ${open.filter(r => r.impact === 'High' && r.type !== 'A').length ? 'style="color:#c0393a"' : ''}>${open.filter(r => r.impact === 'High' && r.type !== 'A').length}</div><div class="l">High risks and issues</div></div><div class="card stat"><div class="v">${I().list('minutes').length}</div><div class="l">Meetings minuted</div></div></div>`;
    return head + `<div class="page-body">${tab === 'pmo' ? (V.pmoView ? V.pmoView() : '') : facts + GT[tab]()}</div>`;
  }, mount() { I().load(KINDS); } };
  ACT.govTab = a => { S.ui.govTab = a.getAttribute('data-v'); V.render(); };
  const GT = {};

  // ----- sign-offs -----
  GT.signoffs = () => `<div class="notice" style="margin-bottom:12px"><span>A sign-off is recorded only when ${esc(custName())} signs here or Facilio records the signature with evidence (an email or a signed document). Generating or exporting a document is never a sign-off.</span></div><div class="grid g3">${SIGNOFFS.map(([k, l, d]) => { const x = I().get('signoff', k) || { status: 'notdue' }; const st = SO_ST[x.status] || SO_ST.notdue;
    return `<div class="card so-card so-${x.status || 'notdue'}"><div class="card-h"><h3>${esc(l)}</h3>${tag(st[0], st[1])}</div><div class="card-b small"><div class="muted" style="margin-bottom:8px">${esc(d)}</div>
      ${x.due ? `<div>Due ${fmt(x.due)}${x.status === 'requested' && x.due < V.today() ? ' ' + tag('red', 'Overdue') : ''}</div>` : ''}${x.doc ? `<div><a href="${esc(F.safeUrl(x.doc))}" target="_blank" rel="noopener">Document to sign</a></div>` : ''}${x.note ? `<div class="muted">${esc(x.note)}</div>` : ''}
      ${x.status === 'signed' ? `<div style="margin-top:6px"><b>${esc(x.signer || '')}</b>${x.title ? ', ' + esc(x.title) : ''}<div class="xs muted">Signed ${fmt((x.signedAt || '').slice(0, 10))}${x.onBehalf ? ' · recorded by Facilio' : ' · in the portal'}</div>${x.evidence ? `<div class="xs">Evidence: ${/^https?:/.test(x.evidence) ? `<a href="${esc(F.safeUrl(x.evidence))}" target="_blank" rel="noopener">link</a>` : esc(x.evidence)}</div>` : ''}${x.evidenceFile ? `<a href="#" class="xs" data-act="dlFile" data-id="${esc(x.evidenceFile.id)}" data-name="${esc(x.evidenceFile.name)}">${esc(x.evidenceFile.name)}</a>` : ''}</div>` : ''}
      ${x.status === 'concern' ? `<div class="notice err small" style="margin-top:6px"><span><b>Concern:</b> ${esc(x.concern || '')}</span></div>` : ''}
      <div class="row" style="margin-top:10px">${fac() ? `${x.status !== 'signed' ? `<button class="btn sm" data-act="soRequest" data-k="${k}">${x.status === 'requested' ? 'Edit request' : 'Request'}</button><button class="btn sm" data-act="soEmail" data-k="${k}">Email client</button>${own() ? `<button class="btn sm" data-act="soRecord" data-k="${k}">Record signature</button>` : '<span class="xs muted">A project owner records the signature</span>'}` : own() ? `<button class="btn sm" data-act="soReopen" data-k="${k}">Reopen</button>` : ''}${x.status === 'concern' ? `<button class="btn sm" data-act="soReopen" data-k="${k}">Request again</button>` : ''}` : ''}
        ${cust() && x.status === 'requested' && V.custAllow('signoff') ? `<button class="btn sm primary" data-act="soSign" data-k="${k}">Sign</button><button class="btn sm" data-act="soConcern" data-k="${k}">Raise a concern</button>` : ''}</div>
      ${(x.hist || []).length ? `<details style="margin-top:8px"><summary class="xs muted">History (${x.hist.length})</summary>${x.hist.slice().reverse().map(h => `<div class="xs muted">${esc(new Date(h.at).toLocaleString())} · ${esc(h.who)} · ${esc(h.event)}</div>`).join('')}</details>` : ''}</div></div>`; }).join('')}</div>`;
  const soGet = k => I().get('signoff', k) || { label: (SIGNOFFS.find(x => x[0] === k) || [])[1], status: 'notdue' };
  ACT.soRequest = a => { const k = a.getAttribute('data-k'); const x = soGet(k); drawer('Request ' + x.label, `<div class="fgrid"><div><label class="f">Due date</label><input type="date" id="so_due" value="${esc(x.due || '')}"></div><div class="full"><label class="f">Link to the document to sign</label><input type="text" id="so_doc" value="${esc(x.doc || '')}" placeholder="https://…"></div><div class="full"><label class="f">Note to ${esc(custName())}</label><textarea id="so_note" rows="3">${esc(x.note || '')}</textarea></div></div>`, `<button class="btn" data-act="closeDrawer">Cancel</button>${x.status === 'requested' ? `<button class="btn" data-act="soNotDue" data-k="${k}">Withdraw request</button>` : ''}<button class="btn primary" data-act="soRequestSave" data-k="${k}">Request sign-off</button>`); };
  ACT.soRequestSave = a => V.busy(a, async () => { const k = a.getAttribute('data-k'); const doc = val('so_doc'); if (doc && !/^https?:\/\//.test(doc)) { toast('The document link must start with http:// or https://'); return; } await I().put('signoff', k, Object.assign({}, soGet(k), { status: 'requested', due: val('so_due'), doc, note: val('so_note'), requestedAt: new Date().toISOString() })); closeDrawer(); toast('Sign-off requested'); });
  ACT.soNotDue = a => V.busy(a, async () => { const k = a.getAttribute('data-k'); await I().put('signoff', k, Object.assign({}, soGet(k), { status: 'notdue' })); closeDrawer(); });
  ACT.soRecord = a => { const k = a.getAttribute('data-k'); const x = soGet(k); drawer('Record ' + x.label, `<div class="notice small" style="margin-bottom:12px"><span>Record a signature given outside the portal. Evidence is required: the approval email (link or subject line) or the signed document.</span></div><div class="fgrid"><div><label class="f">Signed by</label><input type="text" id="so_signer"></div><div><label class="f">Title</label><input type="text" id="so_title"></div><div><label class="f">Date signed</label><input type="date" id="so_date" value="${V.today()}"></div><div class="full"><label class="f">Evidence (email link or subject)</label><input type="text" id="so_ev"></div><div class="full"><label class="f">Or attach the signed document</label><button class="btn sm" data-act="soPickEv">${ico('upl')}Choose file</button> <span id="so_evfile" class="small muted"></span></div></div>`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="soRecordSave" data-k="${k}">Record signature</button>`); };
  let evFile = null;
  ACT.soPickEv = async () => { const f = (await V.pickFile('.pdf,.png,.jpg,.jpeg,.msg,.eml,.docx'))[0]; if (!f) return; evFile = f; document.getElementById('so_evfile').textContent = f.name; };
  ACT.soRecordSave = a => V.busy(a, async () => { const k = a.getAttribute('data-k'); const signer = val('so_signer'); const ev = val('so_ev'); if (!signer) { toast('Enter who signed'); return; } if (!ev && !evFile) { toast('Add the evidence: an email link or subject, or the signed document'); return; }
    let evidenceFile = null; if (evFile) { const rec = await root.FWBApi.uploadFile(S.project.id, evFile, 'signoff_evidence', { signoff: k }); evidenceFile = { id: rec.id, name: evFile.name }; evFile = null; }
    await I().put('signoff', k, Object.assign({}, soGet(k), { status: 'signed', signer, title: val('so_title'), signedAt: (val('so_date') || V.today()) + 'T12:00:00.000Z', evidence: ev, evidenceFile, onBehalf: true })); closeDrawer(); toast('Signature recorded'); });
  ACT.soReopen = async a => { const k = a.getAttribute('data-k'); if (!(await confirmDialog('Reopen sign-off', 'Set this sign-off back to pending? The earlier signature stays in the history.', 'Reopen', true))) return; const x = soGet(k); await I().put('signoff', k, Object.assign({}, x, { status: 'requested', concern: '' })); };
  ACT.soSign = a => { const k = a.getAttribute('data-k'); drawer('Sign ' + soGet(k).label, `<div class="fgrid"><div><label class="f">Your full name</label><input type="text" id="so_signer" value="${esc(S.user.name || '')}"></div><div><label class="f">Your title</label><input type="text" id="so_title"></div><div class="full"><label class="chk"><input type="checkbox" id="so_conf"> I confirm I have reviewed the document and approve it on behalf of ${esc(custName())}.</label></div></div>`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="soSignSave" data-k="${k}">Sign</button>`); };
  ACT.soSignSave = a => V.busy(a, async () => { if (!val('so_conf')) { toast('Tick the confirmation to sign'); return; } await I().put('signoff', a.getAttribute('data-k'), { status: 'signed', signer: val('so_signer'), title: val('so_title'), confirm: true }); closeDrawer(); toast('Signed — thank you'); });
  ACT.soConcern = a => { const k = a.getAttribute('data-k'); drawer('Raise a concern', `<label class="f">What needs to change before you can sign?</label><textarea id="so_concern" rows="5"></textarea>`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="soConcernSave" data-k="${k}">Send</button>`); };
  ACT.soConcernSave = a => V.busy(a, async () => { await I().put('signoff', a.getAttribute('data-k'), { status: 'concern', concern: val('so_concern') }); closeDrawer(); toast('Concern sent to Facilio'); });
  V.signoffStatus = k => (I().get('signoff', k) || { status: 'notdue' });

  // ----- RAID -----
  GT.raid = () => { const f = S.ui.raidType || ''; const list = I().list('raid').filter(r => !f || rt(r) === f).sort((a, b) => (a.status === 'Closed') - (b.status === 'Closed') || IMPACT.indexOf(a.impact) - IMPACT.indexOf(b.impact) || (a.due || '9').localeCompare(b.due || '9'));
    const allowed = canEdit() && V.custAllow('raid');
    return `<div class="row" style="margin-bottom:12px"><div class="seg">${[['', 'All']].concat(Object.entries(RAID_T)).map(([k, l]) => `<button class="${f === k ? 'on' : ''}" data-act="raidType" data-v="${k}">${l} <span class="muted">${I().list('raid').filter(r => !k || rt(r) === k).length}</span></button>`).join('')}</div><span class="spacer"></span>${allowed ? `<button class="btn primary" data-act="raidEdit">${ico('plus')}Add item</button>` : ''}</div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th style="width:36px"></th><th>Item</th><th>Area</th><th>Impact</th><th>Owner</th><th>Due</th><th>Mitigation / response</th><th>Status</th><th></th></tr></thead><tbody>${list.map(r => `<tr><td><span class="raid-t raid-${esc(rt(r))}" title="${esc(RAID_T[rt(r)])}">${esc(rt(r))}</span></td><td class="small"><b>${esc(r.title)}</b></td><td class="small">${esc(V.modLabel(r.mod))}</td><td>${tag(r.impact === 'High' ? 'red' : r.impact === 'Medium' ? 'tbc' : 'low', r.impact || 'Medium')}</td>
      <td class="small">${esc(V.sideLabel(r.side))}${r.owner ? ' · ' + esc(r.owner) : ''}</td><td class="small" ${r.due && r.due < V.today() && r.status !== 'Closed' ? 'style="color:#c0393a"' : ''}>${fmt(r.due)}</td><td class="small">${esc(r.mitigation || '')}</td><td>${tag(r.status === 'Closed' ? 'green' : r.status === 'Mitigating' ? 'blue' : 'tbc', r.status || 'Open')}</td>
      <td class="acts">${allowed ? `<button class="btn sm ghost" data-act="raidEdit" data-id="${esc(r.id)}" aria-label="Edit">${ico('edit')}</button>` : ''}${fac() ? `<button class="btn sm ghost" data-act="raidDel" data-id="${esc(r.id)}" aria-label="Delete">${ico('trash')}</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="9" class="empty">Nothing logged yet.</td></tr>'}</tbody></table></div>`; };
  ACT.raidType = a => { S.ui.raidType = a.getAttribute('data-v'); V.render(); };
  ACT.raidEdit = a => { const id = a.getAttribute('data-id'); const r = id ? I().get('raid', id) : { type: 'R', impact: 'Medium', status: 'Open', side: V.side() };
    drawer(id ? 'Edit RAID item' : 'Add RAID item', `<div class="fgrid"><div><label class="f">Type</label><select id="rd_type">${Object.entries(RAID_T).map(([k, l]) => `<option value="${k}" ${r.type === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div><div><label class="f">Impact</label><select id="rd_imp">${IMPACT.map(x => `<option ${r.impact === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div>
      <div class="full"><label class="f">Title</label><input type="text" id="rd_title" value="${esc(r.title || '')}"></div><div><label class="f">Area</label><select id="rd_mod">${V.moduleOptions(r.mod, [{ v: 'project', l: 'Project' }])}</select></div>
      ${fac() ? `<div><label class="f">Owner side</label><select id="rd_side"><option value="customer" ${r.side === 'customer' ? 'selected' : ''}>${esc(custName())}</option><option value="facilio" ${r.side !== 'customer' ? 'selected' : ''}>Facilio</option></select></div>` : ''}<div><label class="f">Owner name</label><input type="text" id="rd_owner" value="${esc(r.owner || '')}"></div><div><label class="f">Due</label><input type="date" id="rd_due" value="${esc(r.due || '')}"></div>
      <div><label class="f">Status</label><select id="rd_st">${RAID_ST.map(x => `<option ${r.status === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="full"><label class="f">Mitigation / response</label><textarea id="rd_mit" rows="3">${esc(r.mitigation || '')}</textarea></div></div>
      ${(r.hist || []).length ? `<details style="margin-top:10px"><summary class="xs muted">History</summary>${r.hist.slice().reverse().map(h => `<div class="xs muted">${esc(new Date(h.at).toLocaleString())} · ${esc(h.who)} · ${esc(h.event)}</div>`).join('')}</details>` : ''}`,
      `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="raidSave" data-id="${esc(id || '')}">Save</button>`); };
  ACT.raidSave = a => V.busy(a, async () => { const id = a.getAttribute('data-id'); if (!val('rd_title')) { V.ui.field('rd_title', 'Enter a title'); return; } const old = id ? I().get('raid', id) : {};
    await I().put('raid', id || I().uid('r'), Object.assign({}, old, { type: val('rd_type'), impact: val('rd_imp'), title: val('rd_title'), mod: val('rd_mod'), side: fac() ? val('rd_side') : (old.side || 'customer'), owner: val('rd_owner'), due: val('rd_due'), status: val('rd_st'), mitigation: val('rd_mit') })); closeDrawer(); toast('Saved'); });
  ACT.raidDel = async a => { if (!(await confirmDialog('Delete RAID item', 'Delete this item? Closing it keeps the record; deleting removes it.', 'Delete', true))) return; await I().del('raid', a.getAttribute('data-id')); };
  V.openRisks = () => I().list('raid').filter(r => r.status !== 'Closed' && (r.type === 'R' || r.type === 'I'));

  // ----- decisions -----
  GT.decisions = () => { const list = I().list('decision').sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    return `<div class="row" style="margin-bottom:12px"><span class="small muted">Decisions agreed in workshops, calls and governance meetings. Agreed decisions are listed in the BRD for their module.</span><span class="spacer"></span>${fac() ? `<button class="btn primary" data-act="decEdit">${ico('plus')}Decision</button>` : ''}</div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Date</th><th>Decision</th><th>Area</th><th>Why</th><th>Source</th><th>Status</th><th></th></tr></thead><tbody>${list.map(d => `<tr><td class="small">${fmt(d.date)}</td><td class="small"><b>${esc(d.title)}</b>${d.detail ? `<div>${esc(d.detail)}</div>` : ''}</td><td class="small">${esc(V.modLabel(d.mod))}</td><td class="small">${esc(d.why || '')}</td><td class="small">${esc(d.source || '')}${(d.reqIds || []).length ? `<div class="xs">${d.reqIds.map(r => `<a href="#" data-act="editReq" data-id="${esc(r)}">${esc(r)}</a>`).join(', ')}</div>` : ''}</td><td>${tag(d.status === 'Agreed' ? 'green' : d.status === 'Superseded' ? 'low' : 'tbc', d.status || 'Proposed')}</td><td class="acts">${fac() ? `<button class="btn sm ghost" data-act="decEdit" data-id="${esc(d.id)}" aria-label="Edit">${ico('edit')}</button><button class="btn sm ghost" data-act="decDel" data-id="${esc(d.id)}" aria-label="Delete">${ico('trash')}</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">No decisions recorded.</td></tr>'}</tbody></table></div>`; };
  ACT.decEdit = a => { const id = a.getAttribute('data-id'); const d = id ? I().get('decision', id) : { date: V.today(), status: 'Proposed' }; const reqs = S.ws.requirements || [];
    drawer(id ? 'Edit decision' : 'New decision', `<div class="fgrid"><div class="full"><label class="f">Decision</label><input type="text" id="dc_title" value="${esc(d.title || '')}"></div><div class="full"><label class="f">Detail</label><textarea id="dc_detail" rows="3">${esc(d.detail || '')}</textarea></div><div class="full"><label class="f">Why (business reason)</label><textarea id="dc_why" rows="2">${esc(d.why || '')}</textarea></div>
      <div><label class="f">Area</label><select id="dc_mod">${V.moduleOptions(d.mod, [{ v: 'project', l: 'Project' }])}</select></div><div><label class="f">Date</label><input type="date" id="dc_date" value="${esc(d.date || '')}"></div><div><label class="f">Status</label><select id="dc_st">${DEC_ST.map(x => `<option ${d.status === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div><label class="f">Source (session, call, email)</label><input type="text" id="dc_src" value="${esc(d.source || '')}"></div>
      <div class="full"><label class="f">Linked requirements</label><select id="dc_reqs" multiple size="5" style="height:auto">${reqs.map(r => `<option value="${esc(r.id)}" ${(d.reqIds || []).includes(r.id) ? 'selected' : ''}>${esc(r.id)} — ${esc(r.title)}</option>`).join('')}</select></div></div>`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="decSave" data-id="${esc(id || '')}">Save</button>`); };
  ACT.decSave = a => V.busy(a, async () => { const id = a.getAttribute('data-id'); if (!val('dc_title')) { toast('Enter the decision'); return; } await I().put('decision', id || I().uid('d'), Object.assign({}, id ? I().get('decision', id) : {}, { title: val('dc_title'), detail: val('dc_detail'), why: val('dc_why'), mod: val('dc_mod'), date: val('dc_date'), status: val('dc_st'), source: val('dc_src'), reqIds: Array.from(document.getElementById('dc_reqs').selectedOptions).map(o => o.value) })); closeDrawer(); toast('Decision saved'); });
  ACT.decDel = async a => { if (!(await confirmDialog('Delete decision', 'Delete this decision?', 'Delete', true))) return; await I().del('decision', a.getAttribute('data-id')); };
  V.decisionsFor = mod => I().list('decision').filter(d => d.mod === mod && d.status === 'Agreed');

  // ----- actions -----
  GT.actions = () => V.actionsBlock(null);

  // ----- minutes (manual capture: decisions, actions and risks from lines) -----
  GT.minutes = () => { const list = I().list('minutes').sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    return `<div class="row" style="margin-bottom:12px"><span class="small muted">Paste or type the notes from a call. Lines under Decisions, Actions and Risks become records in their registers.</span><span class="spacer"></span>${fac() ? `<button class="btn primary" data-act="mmEdit">${ico('plus')}Minutes</button>` : ''}</div>
    ${list.map(m => `<div class="card" style="margin-bottom:10px"><div class="card-h"><h3>${esc(m.title)}</h3><span class="small muted">${fmt(m.date)} · ${esc(V.modLabel(m.mod))}</span>${m.link ? `<a class="small" href="${esc(F.safeUrl(m.link))}" target="_blank" rel="noopener">Recording / notes</a>` : ''}${fac() ? `<button class="btn sm ghost" data-act="mmEdit" data-id="${esc(m.id)}" aria-label="Edit">${ico('edit')}</button><button class="btn sm ghost" data-act="mmDel" data-id="${esc(m.id)}" aria-label="Delete">${ico('trash')}</button>` : ''}</div><div class="card-b small">${m.summary ? `<p style="margin-top:0">${esc(m.summary)}</p>` : ''}${m.created ? `<div class="xs muted">Created ${m.created.decisions || 0} decision(s), ${m.created.actions || 0} action(s), ${m.created.risks || 0} RAID item(s)</div>` : ''}${m.notes ? `<details><summary class="xs">Notes</summary><div style="white-space:pre-wrap">${esc(m.notes)}</div></details>` : ''}</div></div>`).join('') || '<div class="card empty">No minutes yet.</div>'}`; };
  ACT.mmEdit = a => { const id = a.getAttribute('data-id'); const dr = id ? {} : (V.mmDraft || {}); V.mmDraft = null; const m = id ? I().get('minutes', id) : Object.assign({ date: V.today() }, dr.base || {});   // dr: minutes made from a transcript (src/mom.js)
    drawer(id ? 'Edit minutes' : 'New meeting minutes', `<div class="fgrid"><div class="full"><label class="f">Meeting</label><input type="text" id="mm_title" value="${esc(m.title || '')}" placeholder="e.g. Weekly status call"></div><div><label class="f">Date</label><input type="date" id="mm_date" value="${esc(m.date || '')}"></div><div><label class="f">Area</label><select id="mm_mod">${V.moduleOptions(m.mod, [{ v: 'project', l: 'Project' }, { v: 'kickoff', l: 'Kick-off' }, { v: 'uat', l: 'UAT' }, { v: 'golive', l: 'Go-live' }])}</select></div>
      <div class="full"><label class="f">Link to recording or notes</label><input type="text" id="mm_link" value="${esc(m.link || '')}"></div><div class="full"><label class="f">Summary</label><textarea id="mm_sum" rows="2">${esc(m.summary || '')}</textarea></div><div class="full"><label class="f">Notes</label><textarea id="mm_notes" rows="6">${esc(m.notes || '')}</textarea></div>
      ${id ? '' : `<div class="full"><label class="f">Decisions (one per line)</label><textarea id="mm_dec" rows="3">${esc(dr.dec || '')}</textarea></div><div class="full"><label class="f">Actions (one per line; start with "C:" for ${esc(custName())} or "F:" for Facilio; "Owner — text"; add a date as YYYY-MM-DD)</label><textarea id="mm_act" rows="3" placeholder="C: Priya — share the site list 2026-11-10&#10;F: send the data templates">${esc(dr.act || '')}</textarea></div><div class="full"><label class="f">Risks or issues (one per line; start with "I:" for an issue)</label><textarea id="mm_risk" rows="2">${esc(dr.risk || '')}</textarea></div>`}</div>`,
      `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="mmSave" data-id="${esc(id || '')}">Save</button>`, { wide: true }); };
  ACT.mmSave = a => V.busy(a, async () => { const id = a.getAttribute('data-id'); if (!val('mm_title')) { toast('Name the meeting'); return; } const mod = val('mm_mod'); const m = Object.assign({}, id ? I().get('minutes', id) : {}, { title: val('mm_title'), date: val('mm_date'), mod, link: val('mm_link'), summary: val('mm_sum'), notes: val('mm_notes') });
    if (!id) { const created = { decisions: 0, actions: 0, risks: 0 }; const src = m.title + (m.date ? ' (' + m.date + ')' : '');
      for (const l of val('mm_dec').split('\n').map(x => x.trim()).filter(Boolean)) { await I().put('decision', I().uid('d'), { title: l, mod, date: m.date, status: 'Agreed', source: src }, { silent: true }); created.decisions++; }
      created.actions = await V.actionsFromLines(val('mm_act'), mod, src);
      for (const l of val('mm_risk').split('\n').map(x => x.trim()).filter(Boolean)) { const issue = /^i\s*[:\-]/i.test(l); await I().put('raid', I().uid('r'), { type: issue ? 'I' : 'R', title: l.replace(/^[ri]\s*[:\-]\s*/i, ''), mod, impact: 'Medium', side: 'facilio', status: 'Open', from: src }, { silent: true }); created.risks++; }
      m.created = created; }
    await I().put('minutes', id || I().uid('m'), m); closeDrawer(); toast('Minutes saved'); });
  ACT.mmDel = async a => { if (!(await confirmDialog('Delete minutes', 'Delete these minutes? Decisions, actions and risks created from them are kept.', 'Delete', true))) return; await I().del('minutes', a.getAttribute('data-id')); };

  // ----- module owners -----
  GT.owners = () => { const mods = F.allModules().filter(m => m.inScope && !V.controls().hiddenModules.includes(m.name)).sort((a, b) => F.businessRank(a) - F.businessRank(b)); const ses = F.doc('planner').sessions || [];
    return `<div class="small muted" style="margin-bottom:10px">Who on the ${esc(custName())} side decides for each module, and the Facilio lead.</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Module</th><th>${esc(custName())} owner</th><th>Title</th><th>Facilio lead</th><th>Workshop</th></tr></thead><tbody>${mods.map(m => { const o = I().get('owner', F.slug(m.name)) || {}; const s = ses.find(x => (x.modules || []).includes(m.name) && x.status !== 'cancelled');
      return `<tr><td><b>${esc(m.label)}</b></td><td>${fac() ? `<input type="text" data-change="ownSave" data-m="${esc(m.name)}" data-k="name" value="${esc(o.name || '')}" placeholder="To be named" style="height:30px">` : esc(o.name || 'To be named')}</td><td>${fac() ? `<input type="text" data-change="ownSave" data-m="${esc(m.name)}" data-k="title" value="${esc(o.title || '')}" style="height:30px">` : esc(o.title || '')}</td>
        <td class="small">${fac() ? `<input type="text" data-change="ownSave" data-m="${esc(m.name)}" data-k="lead" value="${esc(o.lead || '')}" placeholder="${esc(S.ws.project.consultant || '')}" style="height:30px">` : esc(V.custShow('trainers') ? (o.lead || S.ws.project.consultant || 'Facilio team') : 'Facilio team')}</td><td class="small">${s && s.date ? 'Session ' + esc(s.no) + ' · ' + fmt(s.date) : '<span class="muted">Not scheduled</span>'}</td></tr>`; }).join('') || '<tr><td colspan="5" class="empty">No modules in scope.</td></tr>'}</tbody></table></div>`; };
  ACT.ownSave = el => V.busy(null, async () => { const m = el.getAttribute('data-m'); const id = F.slug(m); const o = Object.assign({ mod: m }, I().get('owner', id) || {}); o[el.getAttribute('data-k')] = el.value.trim(); await I().put('owner', id, o, { silent: true }); toast('Saved'); });
  V.moduleOwner = m => I().get('owner', F.slug(m));

  // ----- weekly digest (built from the records; nothing invented) -----
  function digestDraft() {
    const t = V.today(), wk = V.addDays(t, -7), next = V.addDays(t, 14), in7 = V.addDays(t, 7); const acts = I().list('action'); const cn = custName();
    const L = (h, arr) => arr.length ? `${h}\n${arr.slice(0, 10).map(x => '• ' + x).join('\n')}\n` : '';
    const doneWk = acts.filter(a => a.status === 'Done' && (a.doneAt || '').slice(0, 10) >= wk).map(a => a.text).concat(I().list('signoff').filter(s => s.status === 'signed' && (s.signedAt || '').slice(0, 10) >= wk).map(s => s.label + ' signed by ' + s.signer));
    const due = side => acts.filter(a => a.side === side && a.status !== 'Done' && a.due && a.due <= in7).map(a => (a.due < t ? 'OVERDUE (was due ' + V.fmtDate(a.due) + '): ' : V.fmtDate(a.due) + ': ') + a.text + (a.owner ? ' — ' + a.owner : ''));
    const sessions = (F.doc('planner').sessions || []).filter(s => s.status !== 'cancelled' && s.date && s.date >= t && s.date <= next).map(s => V.fmtDate(s.date) + ': Session ' + s.no + ' — ' + s.title);
    const waiting = I().list('signoff').filter(s => s.status === 'requested' || s.status === 'concern').map(s => s.label + (s.status === 'concern' ? ' — concern raised' : s.due ? ' — due ' + V.fmtDate(s.due) : ''));
    const crs = I().list('cr').filter(c => c.status === 'Proposed' && c.published).map(c => 'CR-' + String(c.n || '').padStart(3, '0') + ' ' + c.title);
    const risks = V.openRisks().filter(r => r.impact === 'High').map(r => r.title + (r.mitigation ? ' — ' + r.mitigation : ''));
    const onb = V.onboardingDigest ? V.onboardingDigest() : [];
    const phase = V.phaseNow ? V.phaseNow() : null;
    const subject = `${cn} × Facilio · Weekly Update · ${V.fmtDate(t)}`;
    const body = [phase ? `Current stage: ${V.stageOfStep ? 'Stage ' + V.stageOfStep(phase.n - 1) + ' · ' + V.roadmapName(V.stageOfStep(phase.n - 1)) + ' (plan step ' + phase.n + ' of 12: ' + phase.title + ')' : 'Step ' + phase.n + ' of 12: ' + phase.title}${phase.note ? ' (' + phase.note + ')' : ''}\n` : '', L('Done this week', doneWk), L('Coming up (next two weeks)', sessions), L('Due from ' + cn, due('customer')), L('Due from Facilio', due('facilio')), L('Waiting on sign-off', waiting), L('Change requests awaiting your approval', crs), L('High risks', risks), L('Data onboarding', onb)].filter(Boolean).join('\n') + '\nKind regards,\nFacilio Implementation Team';
    return { subject, body };
  }
  V.digestDraft = digestDraft;
  GT.digest = () => { const d = digestDraft(); const posted = I().list('digest').sort((a, b) => (b.at || '').localeCompare(a.at || ''))[0];
    return `<div class="grid g2"><div class="card"><div class="card-h"><h3>This week's update</h3><span class="small muted">Built from actions, sessions, sign-offs, change requests, risks and onboarding</span></div><div class="card-b"><label class="f">Subject</label><input type="text" id="dg_subj" value="${esc(d.subject)}"><label class="f" style="margin-top:10px">Message</label><textarea id="dg_body" rows="18" style="font-family:inherit">${esc(d.body)}</textarea>
      <div class="row" style="margin-top:10px"><button class="btn primary" data-act="dgPost">Post to the customer Overview</button><button class="btn" data-act="dgMail">Open in email</button><button class="btn" data-act="dgOutlook" title="Opens a draft in Outlook on the web. Nothing is sent.">Compose in Outlook</button><button class="btn" data-act="openOutlook">Open Outlook</button><button class="btn" data-act="dgCopy">${ico('copy')}Copy</button></div>${canEdit() && !cust() && !S.readonly ? `<div class="row" style="margin-top:8px"><button class="btn sm ai-btn" data-act="dgAi" title="DeepSeek rewrites the text above in plain words. Nothing is posted or sent.">✦ Polish with DeepSeek</button><button class="btn sm" data-act="dgClaude" title="Claude writes it and saves it as a draft under Deliverables & AI">Ask Claude</button><span class="xs muted">Nothing is posted or sent. You still press Post or send.</span></div>` : ''}</div></div>
      <div class="card"><div class="card-h"><h3>Posted</h3></div><div class="card-b small">${posted ? `<b>${esc(posted.subject)}</b><div class="xs muted">${esc(new Date(posted.at).toLocaleString())}</div><div style="white-space:pre-wrap;margin-top:8px">${esc(posted.body)}</div><button class="btn sm" style="margin-top:8px" data-act="dgUnpost" data-id="${esc(posted.id)}">Remove from the Overview</button>` : '<span class="muted">Nothing posted yet. A posted update shows on the customer Overview for 21 days.</span>'}</div></div></div>`; };
  ACT.dgPost = a => V.busy(a, async () => { await I().put('digest', 'd_' + V.today(), { subject: val('dg_subj'), body: val('dg_body'), posted: true, at: new Date().toISOString() }); toast('Posted to the Overview'); });
  ACT.dgUnpost = a => V.busy(a, async () => { const x = I().get('digest', a.getAttribute('data-id')); await I().put('digest', x.id, Object.assign({}, x, { posted: false })); });
  ACT.dgMail = () => { const b = val('dg_body').slice(0, 1800); root.open('mailto:?subject=' + encodeURIComponent(val('dg_subj')) + '&body=' + encodeURIComponent(b), '_blank'); };
  ACT.dgOutlook = () => V.outlook.compose({ subject: val('dg_subj'), body: val('dg_body') });
  // AI polish of the weekly update: the draft figures above are the only data sent; the answer replaces the message box text and nothing is posted or sent by itself
  const dgIns = () => ('Draft to rewrite: ' + val('dg_body')).slice(0, 1480);
  const dgFill = t => { const el = document.getElementById('dg_body'); if (el) { el.value = t; toast('Draft filled. Read it, then post or send it yourself.'); } else toast('Draft saved under Deliverables & AI', 5000); };
  ACT.dgAi = a => V.busy(a, async () => { try { await V.reportAi({ task: 'govupdate', label: 'Weekly update', instruction: dgIns(), onText: dgFill }); } catch (e) { toast(e.message || 'The AI could not complete this', 6000, true); } });
  ACT.dgClaude = a => V.busy(a, async () => { await V.reportClaude({ task: 'govupdate', label: 'weekly update to the customer', instruction: dgIns() }); });
  ACT.dgCopy = async () => { try { await navigator.clipboard.writeText(val('dg_subj') + '\n\n' + val('dg_body')); toast('Copied'); } catch (e) { toast('Copy is blocked by the browser — select the text and copy it'); } };
  V.latestDigest = () => I().list('digest').filter(d => d.posted && d.at && V.daysBetween(d.at.slice(0, 10), V.today()) <= 21).sort((a, b) => b.at.localeCompare(a.at))[0] || null;

  // ================= change requests =================
  const CR_ST = ['Requested', 'Draft', 'Proposed', 'CR Converted', 'Waived Off', 'Rejected', 'Delivered']; const CR_CLS = { Requested: 'tbc', Draft: 'low', Proposed: 'blue', 'CR Converted': 'green', 'Waived Off': 'tbc', Rejected: 'red', Delivered: 'green' };
  const crNo = c => 'CR-' + String(c.n || 0).padStart(3, '0');
  function rates() { const c = F.doc('contract') || {}; I().load(['ctrrates']); const kc = ((I().get('ctrrates', 'main') || {}).rates || []).map(r => ({ role: r.role, price: Number(String(r.rate || '').replace(/[^0-9.]/g, '')), unit: r.unit || 'day' })); return (c.rateCard || []).concat(kc).filter(r => Number(r.price) > 0).map(r => ({ label: r.role || r.label || 'Rate', price: Number(r.price), unit: r.unit || '', day: /man-?day|per day|day rate|daily/i.test((r.unit || '') + ' ' + (r.role || r.label || '')) })); }
  V.changes = { html() {
    I().load(['cr']); const head = `<div class="page-header"><div class="t"><h1>Change Requests</h1><p>${cust() ? 'Changes to the agreed scope: ask for one, review the estimate and approve or decline it.' : 'Scope changes with effort, price and timeline effect. Customers see a change request only once it is published, and their own requests.'}</p></div><div class="row">${canEdit() && V.custAllow('cr') ? `<button class="btn primary" data-act="crEdit">${ico('plus')}${cust() ? 'Request a change' : 'Change request'}</button>` : ''}</div></div>`;
    if (!I().ready(['cr'])) return head + '<div class="page-body"><div class="empty">Loading…</div></div>';
    const list = I().list('cr').sort((a, b) => (b.n || 0) - (a.n || 0)); const val2 = c => Number(c.price) || 0;
    const sum = st => list.filter(c => st.includes(c.status)).reduce((s, c) => s + val2(c), 0);
    const dash = fac() ? `<div class="grid g4" style="margin-bottom:16px"><div class="card stat"><div class="v">${money(sum(['CR Converted', 'Delivered']))}</div><div class="l">Converted (billable)</div></div><div class="card stat"><div class="v">${money(sum(['Waived Off']))}</div><div class="l">Waived off · ${list.filter(c => c.status === 'Waived Off').reduce((s, c) => s + (Number(c.slipDays) || 0), 0)} days slippage</div></div><div class="card stat"><div class="v">${money(sum(['Proposed', 'Requested', 'Draft']))}</div><div class="l">Pipeline</div></div><div class="card stat"><div class="v" ${list.reduce((s, c) => s + (Number(c.slipDays) || 0), 0) > 0 ? 'style="color:#c0393a"' : ''}>${list.filter(c => c.status !== 'Rejected').reduce((s, c) => s + (Number(c.slipDays) || 0), 0)} days</div><div class="l">Total timeline effect</div></div></div>
      <div class="grid g2" style="margin-bottom:16px"><div class="card"><div class="card-h"><h3>Value by status</h3></div><div class="card-b">${bars(CR_ST.map(s => [s, sum([s]), CR_CLS[s]]).filter(x => x[1] > 0), money)}</div></div><div class="card"><div class="card-h"><h3>Slippage by module</h3></div><div class="card-b">${bars(Object.entries(list.filter(c => c.status !== 'Rejected').reduce((m, c) => { const k = V.modLabel(c.mod); m[k] = (m[k] || 0) + (Number(c.slipDays) || 0); return m; }, {})).filter(x => x[1] > 0).map(([k, v]) => [k, v, 'red']), v => v + ' days')}</div></div></div>`
      : `<div class="grid g3" style="margin-bottom:16px"><div class="card stat"><div class="v">${list.length}</div><div class="l">Change requests</div></div><div class="card stat"><div class="v">${list.filter(c => c.status === 'Proposed').length}</div><div class="l">Awaiting your decision</div></div><div class="card stat"><div class="v">${V.custShow('fees') ? money(sum(['CR Converted', 'Delivered'])) : list.filter(c => ['CR Converted', 'Delivered'].includes(c.status)).length}</div><div class="l">Approved</div></div></div>`;
    return head + `<div class="page-body">${dash}<div class="tbl-wrap"><table class="tbl"><thead><tr><th>No.</th><th>Change</th><th>Area</th><th>Effort</th><th>Price</th><th>Timeline</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c => `<tr><td class="mono">${crNo(c)}</td><td class="small"><b>${esc(c.title)}</b>${c.description ? `<div>${esc(c.description)}</div>` : ''}${c.why ? `<div class="xs muted">Why: ${esc(c.why)}</div>` : ''}<div class="xs muted">${c.side === 'customer' ? 'Requested by ' + esc(custName()) : 'Raised by Facilio'}${fac() && !c.published ? ' · not published' : ''}</div></td><td class="small">${esc(V.modLabel(c.mod))}</td><td class="small">${c.effort ? esc(c.effort) + ' days' : '—'}</td><td class="small">${!cust() || V.custShow('fees') || c.status === 'Proposed' ? money(c.price) : '—'}</td><td class="small">${c.slipDays ? '+' + esc(c.slipDays) + ' days' : '—'}</td>
      <td>${tag(CR_CLS[c.status] || 'low', c.status)}${fac() && AGREED.includes(c.status) && !c.impactReviewedAt ? `<div>${tag('tbc', 'Impact review pending')}</div>` : ''}${c.decisionBy ? `<div class="xs muted">${esc(c.decisionBy)} · ${fmt((c.decidedAt || '').slice(0, 10))}</div>` : ''}</td><td class="acts">${cust() && c.status === 'Proposed' && V.custAllow('cr') ? `<button class="btn sm primary" data-act="crDecide" data-id="${esc(c.id)}">Review</button>` : ''}${(fac() || (cust() && c.side === 'customer' && c.status === 'Requested')) ? `<button class="btn sm ghost" data-act="crEdit" data-id="${esc(c.id)}" aria-label="Edit">${ico('edit')}</button>` : ''}${fac() ? `<button class="btn sm" data-act="crImpact" data-id="${esc(c.id)}" title="Records and documents this change may affect">Impact</button><button class="btn sm ghost" data-act="crDel" data-id="${esc(c.id)}" aria-label="Delete">${ico('trash')}</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="8" class="empty">No change requests.</td></tr>'}</tbody></table></div></div>`;
  }, mount() { I().load(['cr']); if (fac()) I().load(['usecase', 'uat', 'task', 'ugd']); } };
  function bars(rows, f) { const mx = Math.max(1, ...rows.map(r => r[1])); return rows.map(([l, v, cls]) => `<div class="hbar"><span class="small">${esc(l)}</span><span class="hbar-t"><i class="hb-${cls}" style="width:${Math.max(3, v / mx * 100)}%"></i></span><span class="small">${esc(f(v))}</span></div>`).join('') || '<div class="small muted">Nothing yet.</div>'; }
  ACT.crEdit = a => { const id = a.getAttribute('data-id'); const c = id ? I().get('cr', id) : { status: cust() ? 'Requested' : 'Draft', side: V.side() }; const rs = rates();
    const facFields = fac() ? `<div><label class="f">Status</label><select id="cr_st">${CR_ST.map(x => `<option ${c.status === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div><label class="f">Effort (days)</label><input type="number" id="cr_eff" min="0" step="0.5" value="${esc(c.effort || '')}" data-change="crCalc"></div>
      <div><label class="f">Day rate</label><select id="cr_rate" data-change="crCalc">${rs.map(r => `<option value="${r.price}" ${Number(c.rate) === r.price ? 'selected' : ''}>${esc(r.label)} · ${money(r.price)}${r.unit ? ' / ' + esc(r.unit) : ''}</option>`).join('')}<option value="custom" ${c.rate && !rs.some(r => r.price === Number(c.rate)) ? 'selected' : ''}>Another rate…</option></select>${rs.length ? '' : '<div class="xs muted">No rate card in Know Your Contract yet.</div>'}</div><div><label class="f">Custom rate</label><input type="number" id="cr_rate2" min="0" value="${esc(c.rate && !rs.some(r => r.price === Number(c.rate)) ? c.rate : '')}" data-change="crCalc"></div>
      <div><label class="f">Price (${esc(cur())})</label><input type="number" id="cr_price" min="0" value="${esc(c.price || '')}" data-change="crPriceSet"></div><div><label class="f">Timeline effect (days of slippage)</label><input type="number" id="cr_slip" min="0" value="${esc(c.slipDays || '')}"></div><div class="full"><label class="chk"><input type="checkbox" id="cr_pub" ${c.published ? 'checked' : ''}> Published — ${esc(custName())} can see it</label></div>` : '';
    drawer(id ? crNo(c) + ' · ' + c.title : (cust() ? 'Request a change' : 'New change request'), `<div class="fgrid"><div class="full"><label class="f">Title</label><input type="text" id="cr_title" value="${esc(c.title || '')}"></div><div><label class="f">Area</label><select id="cr_mod">${V.moduleOptions(c.mod, [{ v: 'project', l: 'Project' }])}</select></div><div class="full"><label class="f">What should change</label><textarea id="cr_desc" rows="4">${esc(c.description || '')}</textarea></div><div class="full"><label class="f">Why it is needed</label><textarea id="cr_why" rows="2">${esc(c.why || '')}</textarea></div>${facFields ? '<details class="adv full"' + (id ? ' open' : '') + '><summary>More options for the team: status, effort and impact</summary><div class="fgrid" style="margin-top:10px">' + facFields + '</div></details>' : ''}</div>
      ${(c.hist || []).length ? `<details style="margin-top:10px"><summary class="xs muted">History</summary>${c.hist.slice().reverse().map(h => `<div class="xs muted">${esc(new Date(h.at).toLocaleString())} · ${esc(h.who)} · ${esc(h.event)}</div>`).join('')}</details>` : ''}`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn primary" data-act="crSave" data-id="${esc(id || '')}">${cust() && !id ? 'Send request' : 'Save'}</button>`, { wide: true }); };
  let priceManual = false;
  ACT.crPriceSet = () => { priceManual = true; };
  ACT.crCalc = () => { if (priceManual) return; const e = Number(val('cr_eff')) || 0; const r = val('cr_rate') === 'custom' ? Number(val('cr_rate2')) || 0 : Number(val('cr_rate')) || 0; if (e && r) document.getElementById('cr_price').value = Math.round(e * r * 100) / 100; };
  ACT.crSave = a => V.busy(a, async () => { const id = a.getAttribute('data-id'); if (!val('cr_title')) { V.ui.field('cr_title', 'Give the change a title'); return; } const old = id ? I().get('cr', id) : null;
    const d = Object.assign({}, old || {}, { title: val('cr_title'), mod: val('cr_mod'), description: val('cr_desc'), why: val('cr_why') });
    if (fac()) { const rate = val('cr_rate') === 'custom' ? Number(val('cr_rate2')) || 0 : Number(val('cr_rate')) || 0; Object.assign(d, { status: val('cr_st'), effort: Number(val('cr_eff')) || 0, rate, price: Number(val('cr_price')) || 0, priceSet: priceManual || (old && old.priceSet), slipDays: Number(val('cr_slip')) || 0, published: !!val('cr_pub') }); if (d.published && !(old && old.published)) d.publishedAt = new Date().toISOString(); if (!old) { d.side = 'facilio'; } }
    if (!old) d.n = Math.max(0, ...I().list('cr').map(c => c.n || 0)) + 1;
    await I().put('cr', id || I().uid('cr'), d); priceManual = false; closeDrawer(); toast(cust() && !id ? 'Request sent to Facilio' : 'Saved'); });
  ACT.crDecide = a => { const c = I().get('cr', a.getAttribute('data-id')); drawer(crNo(c) + ' · ' + c.title, `<div class="small"><p style="margin-top:0">${esc(c.description || '')}</p><dl class="kv"><dt>Effort</dt><dd>${c.effort ? esc(c.effort) + ' days' : '—'}</dd><dt>Price</dt><dd>${money(c.price)}</dd><dt>Timeline effect</dt><dd>${c.slipDays ? '+' + esc(c.slipDays) + ' days' : 'None'}</dd></dl></div><div class="fgrid" style="margin-top:12px"><div><label class="f">Your name</label><input type="text" id="cr_by" value="${esc(S.user.name || '')}"></div><div class="full"><label class="f">Note (optional)</label><textarea id="cr_note" rows="3"></textarea></div></div>`, `<button class="btn" data-act="closeDrawer">Cancel</button><button class="btn danger" data-act="crDecideSave" data-id="${esc(c.id)}" data-v="Rejected">Decline</button><button class="btn primary" data-act="crDecideSave" data-id="${esc(c.id)}" data-v="CR Converted">Approve</button>`); };
  ACT.crDecideSave = a => V.busy(a, async () => { if (!val('cr_by')) { V.ui.field('cr_by', 'Enter your name'); return; } const cid = a.getAttribute('data-id'); await I().put('cr', cid, Object.assign({}, I().get('cr', cid), { status: a.getAttribute('data-v'), decisionBy: val('cr_by'), decisionNote: val('cr_note'), decidedAt: new Date().toISOString() })); /* the whole record: the route replaces it, so a partial update used to erase the title, description and price */ closeDrawer(); toast(a.getAttribute('data-v') === 'Rejected' ? 'Declined' : 'Approved'); });
  ACT.crDel = async a => { if (!(await confirmDialog('Delete change request', 'Delete this change request?', 'Delete', true))) return; await I().del('cr', a.getAttribute('data-id')); };
  /* Change impact (lifecycle audit, 28 Oct 2026): nothing in the app rewrites approved documents when a change request is agreed, so this lists
     the records and documents that touch the same area for a person to review: requirements, use cases, UAT sessions, tasks, user guides,
     and the BRD / FTR when the area is part of them. Matching is by the change's area (module); it is a review list, not an automatic update. */
  const AGREED = ['CR Converted', 'Waived Off', 'Delivered'];
  function impactOf(c) {
    const m = c.mod || ''; const lab = String(V.modLabel(m) || '').toLowerCase(); const hit = mods => (mods || []).some(x => x === m || String(V.modLabel(x)).toLowerCase() === lab);
    const txt = o => JSON.stringify(o || {}).toLowerCase(); const out = [];
    if (!m || m === 'project') return out;
    (S.ws.requirements || []).filter(r => hit(r.modules) && !/^(Rejected|Deferred)$/.test(r.status)).forEach(r => out.push({ area: 'Requirement', item: r.id + ' · ' + (r.title || ''), note: r.status, view: 'transcripts', ui: { trTab: 'register' } }));
    I().list('usecase').filter(u => hit(u.modules) || u.module === m || (lab && txt(u).includes(lab))).forEach(u => out.push({ area: 'Use case', item: u.title || u.id, view: 'usecases' }));
    I().list('uat').filter(u => u.mod === m).forEach(u => out.push({ area: 'UAT session', item: u.title || u.id, note: u.date || '', view: 'delivery' }));
    I().list('task').filter(t => t.module && (t.module === m || String(t.module).toLowerCase() === lab)).forEach(t => out.push({ area: 'Task', item: 'T-' + t.n + ' · ' + t.title, note: t.status, view: 'tasks' }));
    I().list('ugd').filter(g => (g.plan && (g.plan.modules || []).some(x => String(x).toLowerCase() === lab)) || (lab && txt(g.sections).includes(lab))).forEach(g => out.push({ area: 'User guide', item: g.title, note: g.status === 'approved' ? 'approved: reopen to change' : 'draft', view: 'guidebuilder', ui: { ugOpen: g.id } }));
    const mv = F.moduleView ? F.moduleView(m) : null; if (mv && mv.inScope) { out.push({ area: 'BRD', item: 'Module section: ' + mv.label, note: 'regenerate or edit the section', view: 'brd' }); out.push({ area: 'FTR', item: 'Scenarios for ' + mv.label, note: 'check the FTR rows for this module', view: 'ftr' }); }
    return out;
  }
  V.crImpact = impactOf;
  ACT.crImpact = async a => {
    const c = I().get('cr', a.getAttribute('data-id')); if (!c) return; await I().load(['usecase', 'uat', 'task', 'ugd']); for (let i = 0; i < 30 && !I().ready(['usecase', 'uat', 'task', 'ugd']); i++) await new Promise(r => setTimeout(r, 100)); const im = impactOf(c); const ag = AGREED.includes(c.status);
    drawer(crNo(c) + ' · impact', `<p class="small" style="margin-top:0">${ag ? 'This change is agreed. Nothing is updated automatically: review each record below and change it where the agreed change applies.' : 'This change is <b>not agreed yet</b> (' + esc(c.status) + '). Use this list to assess its impact; do not change approved documents until it is agreed.'} Area: <b>${esc(V.modLabel(c.mod))}</b>.</p>
      ${im.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Type</th><th>Record</th><th>Note</th><th></th></tr></thead><tbody>${im.map((x, i) => `<tr><td class="small">${esc(x.area)}</td><td class="small"><b>${esc(x.item)}</b></td><td class="xs muted">${esc(x.note || '')}</td><td><button class="btn sm ghost" data-act="crImpactGo" data-i="${i}" data-id="${esc(c.id)}">Open</button></td></tr>`).join('')}</tbody></table></div>` : `<div class="notice"><span>No requirement, use case, UAT session, task, guide or BRD module is recorded for this area${c.mod ? '' : ' (the change has no area; set one to see its impact)'}.</span></div>`}
      ${c.impactReviewedAt ? `<p class="xs muted">Impact reviewed by ${esc(c.impactReviewedBy || '')} on ${fmt(String(c.impactReviewedAt).slice(0, 10))}.</p>` : ''}`,
      `<button class="btn" data-act="closeDrawer">Close</button><span class="spacer"></span>${ag && !c.impactReviewedAt ? `<button class="btn primary" data-act="crImpactDone" data-id="${esc(c.id)}">Mark impact reviewed</button>` : ''}`, { wide: true });
  };
  ACT.crImpactGo = a => { const c = I().get('cr', a.getAttribute('data-id')); const x = impactOf(c)[Number(a.getAttribute('data-i'))]; closeDrawer(); if (!x) return; Object.assign(S.ui, x.ui || {}); V.go(x.view); };
  ACT.crImpactDone = a => V.busy(a, async () => { const cid = a.getAttribute('data-id'); await I().put('cr', cid, Object.assign({}, I().get('cr', cid), { impactReviewedBy: S.user.name || S.user.email, impactReviewedAt: new Date().toISOString() })); closeDrawer(); toast('Impact review recorded'); });
  V.crNo = crNo;
})(typeof window !== 'undefined' ? window : globalThis);
